// Koji leadovi: ručno pokretanje = svi od pokretanja kampanje, raspored u 9:00 = jučerašnji dan
const daily = $('Svako jutro u 9').isExecuted;
const mode = daily ? 'daily' : 'all';
const W = daily
  ? "timestamp >= toStartOfDay(now()) - INTERVAL 1 DAY AND timestamp < toStartOfDay(now())"
  : "timestamp >= toDateTime('2026-11-26 16:00:00')";
const AD = "(properties.utm_medium = 'paid_social' OR person.properties.$initial_utm_medium = 'paid_social')";
const q1 = `SELECT person.properties.email AS email, argMin(properties.name, timestamp), any(person.properties.phone), argMin(properties.gender, timestamp), argMin(properties.age, timestamp), argMin(properties.goal, timestamp), argMin(properties.bodytype, timestamp), argMin(properties.motivation, timestamp), argMin(properties.struggle, timestamp), argMin(properties.tried, timestamp), argMin(properties.diet, timestamp), argMin(properties.fear, timestamp), min(timestamp), argMin(coalesce(properties.utm_content, person.properties.$initial_utm_content), timestamp) FROM events WHERE event = 'quiz_completed' AND ${AD} AND ${W} AND notEmpty(toString(person.properties.email)) GROUP BY email ORDER BY min(timestamp) LIMIT 2000`;
const q2 = `SELECT person.properties.email AS email, countIf(event = 'vsl_50') > 0, countIf(event = 'vsl_checkout_clicked') > 0, countIf(event = 'purchase') > 0, countIf(event = 'vsl_whatsapp_clicked') > 0 FROM events WHERE event IN ('vsl_50', 'vsl_checkout_clicked', 'purchase', 'vsl_whatsapp_clicked') AND timestamp >= toDateTime('2026-11-20 00:00:00') AND person_id IN (SELECT person_id FROM events WHERE event = 'quiz_completed' AND ${W}) GROUP BY email LIMIT 5000`;
return [{ json: { mode, q1, q2 } }];

// Složi mail s leadovima iz oglasa (HTML + CSV prilog za Excel)
const cfg = $('Config').first().json;
const mode = $('Upiti').first().json.mode; // 'all' | 'daily'
const leadsRows = ($('PostHog: leadovi').first().json.results) || [];
const statusRows = ($('PostHog: statusi').first().json.results) || [];

const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const dash = (v) => (v == null || v === '' ? '—' : String(v));
const tz = 'Europe/Zagreb';
const fmt = (iso) => {
  const d = new Date(iso);
  return isNaN(d) ? '' : d.toLocaleString('hr-HR', { timeZone: tz, day: 'numeric', month: 'numeric', hour: '2-digit', minute: '2-digit' });
};
const fmtDay = (d) => d.toLocaleDateString('hr-HR', { timeZone: tz, day: 'numeric', month: 'numeric', year: 'numeric' });

const status = {};
for (const r of statusRows) status[String(r[0] || '').toLowerCase()] = { half: !!r[1], checkout: !!r[2], bought: !!r[3], wa: !!r[4] };

const skip = String(cfg.SKIP_EMAILS || '').toLowerCase().split(/[\s,;]+/).filter(Boolean);
const leads = [];
for (const r of leadsRows) {
  const email = String(r[0] || '').trim().toLowerCase();
  if (!email || skip.includes(email)) continue;
  const phone = String(r[2] || '').replace(/[^\d+]/g, '');
  const st = status[email] || {};
  leads.push({
    email, name: r[1] && r[1] !== 'Prijatelju' ? String(r[1]) : '', phone,
    gender: r[3], age: r[4], goal: r[5], bodytype: r[6], motivation: r[7], struggle: r[8], tried: r[9], diet: r[10], fear: r[11],
    at: r[12], ad: r[13] || '',
    half: !!st.half, checkout: !!st.checkout, bought: !!st.bought, wa: !!st.wa,
  });
}
// Toplina: kupio na kraj, checkout > pola videa > ostali; unutar iste razine najnoviji prvi
const heat = (l) => (l.bought ? -1 : (l.checkout ? 3 : 0) + (l.half ? 2 : 0) + (l.wa ? 1 : 0));
const sortFn = (a, b) => heat(b) - heat(a) || String(b.at).localeCompare(String(a.at));
const withPhone = leads.filter((l) => l.phone).sort(sortFn);
const hotNoPhone = leads.filter((l) => !l.phone && !l.bought && (l.half || l.checkout)).sort(sortFn);
const rest = leads.filter((l) => !l.phone && !(l.half || l.checkout) || (!l.phone && l.bought)).sort(sortFn);

const badges = (l) => {
  const b = [];
  if (l.bought) b.push(['KUPIO/LA', '#15803d']);
  if (l.checkout && !l.bought) b.push(['kliknuo/la checkout', '#b91c1c']);
  if (l.half) b.push(['pogledao/la pola videa', '#b45309']);
  if (l.wa) b.push(['kliknuo/la WhatsApp', '#047857']);
  return b.map(([t, c]) => `<b style="background:${c};color:#fff;font-size:11px;padding:1px 6px;border-radius:9px;">${t}</b> `).join('');
};
const card = (l) => {
  const digits = l.phone.replace(/\D/g, '');
  const contact = l.phone
    ? `<a href="tel:${esc(l.phone)}" style="color:#111827;font-weight:bold;font-size:16px;text-decoration:none;">${esc(l.phone)}</a> &nbsp;·&nbsp; <a href="https://wa.me/${digits}" style="color:#047857;font-weight:bold;">WhatsApp</a> &nbsp;·&nbsp; `
    : '';
  return `<tr><td style="padding:12px 14px;border-bottom:1px solid #e5e7eb;">
<div style="font-size:16px;font-weight:bold;color:#111827;">${esc(l.name || 'Bez imena')} <span style="font-weight:normal;color:#6b7280;font-size:13px;">${esc(dash(l.gender))}, ${esc(dash(l.age))} · ${esc(fmt(l.at))}</span></div>
<div style="margin:4px 0 6px;">${badges(l)}</div>
<div style="font-size:14px;margin-bottom:6px;">${contact}<a href="mailto:${esc(l.email)}" style="color:#1d4ed8;">${esc(l.email)}</a></div>
<div style="font-size:13px;color:#374151;line-height:1.5;"><b>Cilj:</b> ${esc(dash(l.goal))} · <b>Tip tijela:</b> ${esc(dash(l.bodytype))}<br><b>Najveći problem:</b> ${esc(dash(l.struggle))}<br><b>Strah:</b> ${esc(dash(l.fear))}<br><b>Motivacija:</b> ${esc(dash(l.motivation))}</div>
</td></tr>`;
};
const line = (l) => `<tr><td style="padding:6px 14px;border-bottom:1px solid #f3f4f6;font-size:13px;color:#374151;"><b>${esc(l.name || 'Bez imena')}</b> · <a href="mailto:${esc(l.email)}" style="color:#1d4ed8;">${esc(l.email)}</a> · ${esc(dash(l.goal))} · ${esc(dash(l.bodytype))} <span style="color:#9ca3af;">${esc(fmt(l.at))}</span> ${badges(l)}</td></tr>`;
const section = (title, note, rows) => rows ? `<h2 style="font-size:17px;color:#111827;margin:28px 0 4px;">${title}</h2><p style="margin:0 0 8px;color:#6b7280;font-size:13px;">${note}</p><table width="100%" cellpadding="0" cellspacing="0" style="border:1px solid #e5e7eb;border-radius:8px;border-collapse:separate;">${rows}</table>` : '';

const now = new Date();
const yesterday = new Date(now.getTime() - 24 * 3600 * 1000);
const title = mode === 'all'
  ? `Svi leadovi iz oglasa od 26. 11. 2026. do danas`
  : `Novi leadovi iz oglasa za ${fmtDay(yesterday)}`;
const bought = leads.filter((l) => l.bought).length;
const subject = mode === 'all'
  ? `Svi leadovi iz oglasa: ${leads.length} (${withPhone.length} s brojem)`
  : (leads.length ? `Leadovi iz oglasa ${fmtDay(yesterday)}: ${leads.length} novih (${withPhone.length} s brojem)` : `Leadovi iz oglasa ${fmtDay(yesterday)}: nema novih`);

const html = `<div style="font-family:Arial,Helvetica,sans-serif;max-width:680px;margin:0 auto;color:#111827;">
<h1 style="font-size:21px;margin:0 0 6px;">${title}</h1>
<p style="margin:0 0 4px;font-size:14px;color:#374151;"><b>${leads.length}</b> leadova · <b>${withPhone.length}</b> s brojem mobitela · <b>${hotNoPhone.length}</b> zainteresiranih bez broja${bought ? ` · <b>${bought}</b> kupilo` : ''}</p>
<p style="margin:0;font-size:13px;color:#6b7280;">Unutar svake grupe na vrhu su najtopliji: kliknuli checkout, pa pogledali više od pola videa. Svi leadovi sa svim odgovorima su i u prilogu (leadovi.csv, otvara se u Excelu).</p>
${leads.length ? '' : '<p style="font-size:15px;margin-top:20px;">Jučer nije bilo novih leadova iz oglasa.</p>'}
${section(`📞 S brojem mobitela (${withPhone.length})`, 'Klikni broj za poziv ili WhatsApp za poruku.', withPhone.map(card).join(''))}
${section(`🔥 Zainteresirani bez broja (${hotNoPhone.length})`, 'Pogledali više od pola videa ili kliknuli checkout, a nisu kupili. Javi se mailom.', hotNoPhone.map(line).join(''))}
${section(`Ostali leadovi (${rest.length})`, 'Ostavili email, ali još nisu pokazali veći interes.', rest.map(line).join(''))}
<p style="margin-top:28px;font-size:12px;color:#9ca3af;">Automatski mail iz n8n (workflow "Ursa: dnevni mail leadova"), svako jutro u 9:00 za prethodni dan. Podaci iz PostHoga.</p>
</div>`;

const cols = ['Datum', 'Ime', 'Mobitel', 'Email', 'Spol', 'Dob', 'Cilj', 'Tip tijela', 'Motivacija', 'Najveći problem', 'Što je probao/la', 'Prehrana', 'Strah', 'Oglas', 'Pola videa', 'Checkout', 'WhatsApp klik', 'Kupio/la'];
const csvCell = (v) => { const s = String(v == null ? '' : v); return /[;"\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s; };
const yn = (b) => (b ? 'da' : '');
const csv = [cols.join(';')].concat([...withPhone, ...hotNoPhone, ...rest].map((l) => [fmt(l.at), l.name, l.phone, l.email, l.gender, l.age, l.goal, l.bodytype, l.motivation, l.struggle, l.tried, l.diet, l.fear, l.ad, yn(l.half), yn(l.checkout), yn(l.wa), yn(l.bought)].map(csvCell).join(';'))).join('\r\n');

const to = String(cfg.EMAIL_TO || '').split(/[\s,;]+/).filter(Boolean);
const request = { from: cfg.EMAIL_FROM, to, subject, html };
if (leads.length) request.attachments = [{ filename: 'leadovi.csv', content: Buffer.from('﻿' + csv, 'utf8').toString('base64') }];

return [{ json: { mode, count: leads.length, with_phone: withPhone.length, html_kb: Math.round(html.length / 1024), to_count: to.length, request } }];
